select 


order by settings.evaluation_year desc, settings.area_code, settings.element_code, settings.sort_order, settings.management_item_code
limit #{criteria.safeSize} offset #{criteria.offset}

select 

where settings.rule_version_id = #{ruleVersionId}
  and settings.evaluation_year = #{evaluationYear}
  and settings.area_code = #{areaCode}
  and settings.element_code = #{elementCode}
  and settings.management_item_code = #{managementItemCode}
order by case when versions.version_status = 'DRAFT' then 0 else 1 end, settings.updated_at desc
limit 1
